// ─────────────────────────────────────────────────────
// Session schedule — 5 Mondays with custom motivational copy
// ─────────────────────────────────────────────────────
const sessions = [
  {
    week: 1,
    sendOnMonday: '2026-10-05',
    sessionDate:  'Wednesday 7th October',
    topic:        'Optimize Your Campaigns with Meta Advantage+',
    message: (firstName) => `Hi ${firstName}! Your journey with Meta Transform with AI begins this Wednesday, 7th Oct at 11 AM EAT! In Session 1, we dive into Meta Advantage+ to show you how AI automates audience targeting & budget to find your best paying customers. Don't miss this game-changer! Join link is in your email. - WYLDE`
  },
  {
    week: 2,
    sendOnMonday: '2026-10-12',
    sessionDate:  'Wednesday 14th October',
    topic:        'Optimize Your Ad Creatives with Advantage+',
    message: (firstName) => `Hi ${firstName}! Following our powerful dive into Meta Advantage+ campaigns, this Wednesday 14th Oct at 11 AM EAT we unlock AI Creative Optimization! Discover how AI crafts high-converting ad visuals and copy that stop the scroll and drive orders. See you at 11 AM! - WYLDE`
  },
  {
    week: 3,
    sendOnMonday: '2026-10-19',
    sessionDate:  'Wednesday 21st October',
    topic:        'Opportunity Score',
    message: (firstName) => `Hi ${firstName}! Now that your creatives are stopping the scroll, let's maximize ROI. This Wednesday 21st Oct at 11 AM EAT, discover Meta's "Opportunity Score" - the real-time AI diagnostic that pinpoints exactly how to fix bottlenecks and scale your sales. Be there! - WYLDE`
  },
  {
    week: 4,
    sendOnMonday: '2026-10-26',
    sessionDate:  'Wednesday 28th October',
    topic:        'WhatsApp Business Platform for Effective Business Messaging',
    message: (firstName) => `Hi ${firstName}! With your campaigns optimized, let's close more deals! This Wednesday 28th Oct at 11 AM EAT, explore WhatsApp Business Platform - turning customer chats into instant sales with automated business messaging. Don't miss it! - WYLDE`
  },
  {
    week: 5,
    sendOnMonday: '2026-11-02',
    sessionDate:  'Wednesday 4th November',
    topic:        'Increase Campaign Performance with Partnership Ads',
    message: (firstName) => `Hi ${firstName}! For our 5th & final session this Wednesday 4th Nov at 11 AM EAT, we're unlocking Partnership Ads! Learn how co-branding with creators & partners supercharges trust and explodes your reach. Let's finish strong together! - WYLDE`
  }
];

// Today's date in YYYY-MM-DD
const today = new Date().toISOString().split('T')[0];

// Find matching session for today's Monday
let session = sessions.find(s => s.sendOnMonday === today);

// Fallback for manual testing inside n8n:
if (!session) {
  const isScheduled = typeof $execution !== 'undefined' && $execution && $execution.mode === 'trigger';
  if (isScheduled) {
    // Scheduled run on a non-session week — stop cleanly
    return [];
  }
  // Manual test run — use Session 1 as default preview
  session = sessions[0];
}

const items = $input.all();
return items.map(item => {
  const firstName = (item.json['First Name'] || 'Participant').trim();
  return {
    json: {
      ...item.json,
      sessionWeek:  session.week,
      sessionDate:  session.sessionDate,
      topic:        session.topic,
      smsMessage:   session.message(firstName)
    }
  };
});

// Build the smslist array for Advanta bulk endpoint
// Phone numbers must be in international format without +: 2547XXXXXXXX

const ADVANTA_API_KEY   = 'YOUR_ADVANTA_API_KEY';
const ADVANTA_PARTNER_ID = 'YOUR_ADVANTA_PARTNER_ID';
const ADVANTA_SENDER_ID  = 'YOUR_ADVANTA_SENDER_ID';

const smslist = $input.all().map((item, index) => {
  // Normalise phone: remove spaces, dashes, leading +
  let phone = (item.json['Phone'] || '').replace(/[^0-9]/g, '');
  // Convert 07XXXXXXXX -> 2547XXXXXXXX
  if (phone.startsWith('0')) phone = '254' + phone.slice(1);
  // Convert +254... -> 254...
  if (phone.startsWith('254') === false) phone = '254' + phone;

  return {
    partnerID:    ADVANTA_PARTNER_ID,
    apikey:       ADVANTA_API_KEY,
    pass_type:    'plain',
    clientsmsid:  index + 1,
    mobile:       phone,
    message:      item.json.smsMessage,
    shortcode:    ADVANTA_SENDER_ID
  };
});

return [{
  json: {
    apikey:    ADVANTA_API_KEY,
    partnerID: ADVANTA_PARTNER_ID,
    smslist:   smslist
  }
}];
